/* Keep map actions separate from checkbox labels so navigation never changes progress. */
const viennaMapStops = [["Stephansdom"], ["Graben", "Kohlmarkt"], ["Österreichische Nationalbibliothek Prunksaal"], ["Hofburg", "Heldenplatz", "Volksgarten"], ["Reinthaler’s Beisl"], ["Parlament", "Rathaus", "Burgtheater", "Universität Wien", "Votivkirche"], ["Café Sperl", "Café Jelinek", "Kleines Café"], ["Restaurants Neubau", "Restaurants Spittelberg"], ["Wiener Staatsoper", "Volksoper", "Musikverein", "Konzerthaus"], ["Schönbrunn Palace"], ["Schönbrunn Palace Gardens", "Gloriette"], ["Restaurants Meidling", "Restaurants Mariahilf"], ["Mariahilfer Straße", "Neubaugasse"], ["Mariahilf", "Neubau", "Spittelberg"], ["Otto Wagner Pavillon Karlsplatz", "Majolikahaus"], ["Austrian restaurants Vienna"], ["Kaiserschmarrn Vienna"], ["Upper Belvedere"], ["Belvedere Gardens"], ["Karlskirche", "Secession"], ["Naschmarkt"], ["Kunsthistorisches Museum", "Leopold Museum", "Albertina"], ["MuseumsQuartier"], ["Restaurants Neubau"], ["Neubau"], ["Hundertwasserhaus"], ["Kunst Haus Wien"], ["Wiener Riesenrad"], ["Grüner Prater"], ["Restaurants Karmelitermarkt"], ["Donaukanal"], ["Kahlenberg", "Nussdorf"], ["Heuriger Nussdorf", "Heuriger Grinzing", "Heuriger Neustift am Walde"], ["Heuriger Vienna"]];
const mexicoMapStops = {"juarez": ["Juárez Mexico City"], "reforma": ["Ángel de la Independencia"], "roma": ["Plaza Río de Janeiro Roma Norte", "Colima Roma Norte", "Álvaro Obregón Roma Norte"], "condesa": ["Parque México", "Avenida Amsterdam Condesa"], "drinks": ["Pistilo", "Salón Palomilla"], "otherbar": ["Pistilo", "Salón Palomilla"], "zocalo": ["Zócalo"], "cathedral": ["Catedral Metropolitana"], "templo": ["Museo del Templo Mayor"], "charco": ["CHARCO Centro Histórico"], "bellas": ["Palacio de Bellas Artes"], "alameda": ["Alameda Central"], "moro": ["Churrería El Moro Centro Histórico"], "anthropology": ["Museo Nacional de Antropología"], "park": ["Bosque de Chapultepec"], "castle": ["Castillo de Chapultepec"], "terraces": ["Castillo de Chapultepec"], "frida": ["Museo Frida Kahlo Casa Azul"], "squares": ["Jardín Centenario Coyoacán", "Plaza Hidalgo Coyoacán"], "market": ["Mercado de Coyoacán"], "coffee": ["Cafés Coyoacán"], "early": ["Triver Coliving Florencia 39"], "home": ["Triver Coliving Florencia 39"], "teoti": ["Zona Arqueológica de Teotihuacán"], "avenue": ["Calzada de los Muertos Teotihuacán"], "lunch": ["Restaurants near Zona Arqueológica de Teotihuacán"], "vasconcelos": ["Biblioteca Vasconcelos"], "quetzal": ["Parque Quetzalcóatl Naucalpan"], "frances": ["Panteón Francés de la Piedad Avenida Cuauhtémoc"], "odette": ["ODETTE Lomas de Chapultepec"]};
function addMapLinks(label, places, city) {
 const row=document.createElement('div'); row.className='fn-stop';
 label.before(row); row.append(label);
 const links=document.createElement('div');links.className='fn-map-links';
 for(const place of places){const a=document.createElement('a');a.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(place+', '+(/Teotihuac|Naucalpan/.test(place)?'Mexico':city));a.target='_blank';a.rel='noopener noreferrer';a.textContent=places.length===1?'Map ↗':place+' ↗';a.setAttribute('aria-label','Find '+place+' on Google Maps (opens in a new tab)');links.append(a);}
 row.append(links);
}
if(document.body.classList.contains('fn-vienna')){
 document.querySelectorAll('label.item').forEach((label,i)=>addMapLinks(label,viennaMapStops[i]||[label.querySelector('strong').textContent],'Vienna, Austria'));
}else if(document.body.classList.contains('fn-mexico')){
 document.querySelectorAll('label.task').forEach(label=>{const id=label.querySelector('input').id;addMapLinks(label,mexicoMapStops[id]||[label.querySelector('.task-title').textContent],'Mexico City, Mexico');});
 document.querySelectorAll('.useful li').forEach(li=>{const a=document.createElement('a');a.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(li.querySelector('strong').textContent+', Mexico City, Mexico');a.target='_blank';a.rel='noopener noreferrer';a.className='fn-salon-map';a.textContent='Map ↗';li.append(a);});
}
